func TestFinalityDataDecoding(t *testing.T) {
	bytes, err := hex.DecodeString(strings.ReplaceAll(finalityDataInput, "\n", ""))
	assert.NoError(t, err)

	finalityData := &FinalityData{}
	assert.NoError(t, unmarshalBinary(bytes, finalityData), err)
}

